var tierUp=(WTIER[itm.gk]||0)>_bestT;
var condUp=(WTIER[itm.gk]||0)===_bestT&&(WTIER[itm.gk]||0)===(WTIER[p.wep.id]||0)&&found.qRank>(p.wep.qRank===undefined?1:p.wep.qRank);

